with.tags:
type=raw,value=dev
type=raw,value=qa,enable=${{ github.event_name == 'release' }}
type=raw,value=stable,enable=${{ github.event.action == 'released' }}
type=semver,pattern={{version}},enable=${{ github.event_name == 'release' }}

steps.run:
{
  echo "### Idempotent migrations for ${APP} (${EF_CONTEXT})"
  echo "\`\`\`sql"
  cat "${APP}.sql"
  echo "\`\`\`"
} >> "$GITHUB_STEP_SUMMARY"
